head.b:skin:
/* ===========================================================================
   Masala Deutsch — a Blogger theme built for long, data-heavy analysis posts.
   No third-party JavaScript. No packed/encrypted footer scripts. No web fonts.

   Two design constraints came from real failures on this blog:
   1. Index pages render post SNIPPETS, never full bodies. Rendering full
      bodies blew Blogger's per-page budget on 30-530KB posts and the post
      list silently came back EMPTY.
   2. NO automatic dark mode, at any level. The posts force a white background
      with !important, so a theme-level dark block flips the text to near-white
      while the surface stays white -- the page renders blank. See the note on
      the palette below.
   =========================================================================== */

:root{
  --ink:#0B1F2D;        /* headings, body text  */
  --ink-soft:#43535F;   /* secondary text       */
  --accent:#2251FF;     /* links, rules         */
  --accent-ink:#1B3FCC; /* link hover           */
  --cyan:#00A9F4;       /* kickers, eyebrow rules */
  --bg:#FFFFFF;
  --bg-alt:#F4F7FB;
  --line:#D9E1E8;
  --hero:#0B1F2D;
  --hero-ink:#FFFFFF;
  --serif:Georgia,'Times New Roman',serif;
  --sans:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif;
  --wrap:1080px;
  --measure:70ch;
}
/* NO dark mode. Deliberately, and this was learned the hard way twice.
   The published posts carry their own `body{background:#fff!important}`
   override. A theme-level prefers-color-scheme block flips --ink to near-white
   but CANNOT flip the surface, because the post's !important wins -- so every
   heading and link renders white-on-white and the page reads as blank.
   A theme declares <body>; it does not get the last word on it.
   Light only. Do not re-add a dark block without first removing the
   force-white rules from all 69 post bodies. */

*,*::before,*::after{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:17px/1.65 var(--serif);
  -webkit-text-size-adjust:100%}
img{max-width:100%;height:auto}
a{color:var(--accent);text-underline-offset:2px}
a:hover{color:var(--accent-ink)}
.wrap{max-width:var(--wrap);margin-inline:auto;padding-inline:20px}

/* ---- Header ---------------------------------------------------------- */
.site-head{border-bottom:1px solid var(--line);background:var(--bg);
  position:sticky;top:0;z-index:20}
.site-head .wrap{display:flex;align-items:center;gap:18px;
  justify-content:space-between;min-height:60px;flex-wrap:wrap}
.site-title{font-family:var(--sans);font-weight:700;font-size:1rem;
  letter-spacing:.02em;text-transform:uppercase;color:var(--ink);text-decoration:none}
.site-title span{color:var(--accent)}
.site-nav{font-family:var(--sans);font-size:.82rem;display:flex;gap:16px;flex-wrap:wrap}
.site-nav a{text-decoration:none}
.site-nav a:hover{text-decoration:underline}

/* ---- Hero / featured -------------------------------------------------- */
.hero{background:var(--hero);color:var(--hero-ink);padding:72px 0 66px;margin-bottom:8px}
.hero .kicker{font-family:var(--sans);font-size:.7rem;letter-spacing:.18em;
  text-transform:uppercase;font-weight:700;color:var(--cyan);margin-bottom:14px}
.hero h2{font-size:2.5rem;line-height:1.12;margin:0 0 16px;letter-spacing:-.02em;font-weight:300}
.hero h2 strong{font-weight:700}
.hero h2 a{color:var(--hero-ink);text-decoration:none}
.hero h2 a:hover{text-decoration:underline}
.hero p{color:#C7D4DF;max-width:var(--measure);margin:0 0 16px}
.hero .more{font-family:var(--sans);font-size:.82rem;font-weight:700;
  color:#7FA5FF;text-decoration:none;letter-spacing:.04em;text-transform:uppercase}

/* ---- Post list (index) ------------------------------------------------ */
.section-label{font-family:var(--sans);font-size:.7rem;letter-spacing:.18em;
  text-transform:uppercase;font-weight:700;color:var(--ink);
  border-top:2px solid var(--ink);padding-top:10px;margin:52px 0 0;
  display:block}
.card{border-bottom:1px solid var(--line);padding:32px 0;transition:padding-left .18s}
.card:hover{padding-left:8px}
.card:last-child{border-bottom:none}
.card h3{font-size:1.5rem;line-height:1.22;margin:0 0 8px;letter-spacing:-.015em;font-weight:400}
.card h3 a{color:var(--ink);text-decoration:none}
.card h3 a:hover{color:var(--accent)}
.card .meta{font-family:var(--sans);font-size:.75rem;color:var(--ink-soft);
  margin-bottom:8px;font-variant-numeric:tabular-nums}
.card p{margin:0 0 10px;color:var(--ink-soft);max-width:var(--measure)}
.card .more{font-family:var(--sans);font-size:.78rem;font-weight:700;
  text-decoration:none;letter-spacing:.04em;text-transform:uppercase}

/* ---- Single post ------------------------------------------------------ */
.post-head{padding:52px 0 18px;border-bottom:2px solid var(--ink);margin-bottom:32px}
.post-head h1{font-size:2.6rem;line-height:1.14;margin:0 0 14px;letter-spacing:-.025em;font-weight:300}
.post-head h1 strong{font-weight:700}
.post-head .meta{font-family:var(--sans);font-size:.78rem;color:var(--ink-soft)}
.post-body{font-size:1.02rem}
.post-body p{max-width:var(--measure)}
.post-body h2,.post-body h3{line-height:1.3}
/* Long analysis posts carry wide tables; they scroll in their own box so the
   page body never scrolls sideways on a phone. */
.post-body table{max-width:100%;border-collapse:collapse}
.post-body .table-scroll,.post-body div[style*="overflow"]{overflow-x:auto}
.post-body img{height:auto}

/* ---- Gadget slots in the page body -----------------------------------
   The whole reason this theme exists. Blogger's modern themes (Contempo,
   Soho, Emporio, Notable) allow NO gadgets in the page body, so a
   topic index cannot be placed with the content. These sections do. */
.slot{margin:26px 0}
.slot .widget{margin-bottom:20px}
.slot h2,.slot h3{font-family:var(--sans);font-size:.7rem;letter-spacing:.18em;
  text-transform:uppercase;font-weight:700;color:var(--ink-soft);margin:0 0 10px}
.slot ul{margin:0;padding-left:1.1rem}
.slot li{margin-bottom:5px}

/* ---- Browse-by-topic block (an HTML gadget in the main-bottom slot) ----
   Sits BELOW the recent-article list: newest work first, whole archive after. */
.browse{border-top:2px solid var(--ink);margin-top:40px;padding-top:20px}
.browse-head h2{font-family:var(--sans);font-size:1.15rem;font-weight:700;
  margin:0 0 6px;color:var(--ink);letter-spacing:-.01em}
.browse-head p{font-family:var(--sans);font-size:.85rem;color:var(--ink-soft);margin:0}
.topics{display:grid;grid-template-columns:repeat(auto-fit,minmax(255px,1fr));
  gap:20px 28px;margin:26px 0 8px}
.topic h3{font-family:var(--sans);font-size:.72rem;letter-spacing:.14em;
  text-transform:uppercase;font-weight:700;color:var(--ink);margin:0 0 8px;
  border-bottom:2px solid var(--accent);padding-bottom:5px}
.topic h3 span{color:var(--ink-soft);font-weight:400;letter-spacing:0}
.topic ul{margin:0;padding:0;list-style:none}
.topic li{margin-bottom:6px;line-height:1.4}
.topic a{font-size:.92rem;text-decoration:none;color:var(--ink)}
.topic a:hover{color:var(--accent);text-decoration:underline}
.topics{display:block;margin:26px 0 8px}
.topic{margin:0}
.topic>summary{cursor:pointer;list-style:none;display:flex;align-items:baseline;gap:.7rem;flex-wrap:wrap;border-top:2px solid var(--ink);padding:14px 0;position:relative;padding-right:28px}
.topic>summary::-webkit-details-marker{display:none}
.topic>summary::after{content:"+";position:absolute;right:0;top:14px;font-size:1.3em;font-weight:700;color:var(--accent);line-height:1}
.topic[open]>summary::after{content:"\2212"}
.topic>summary h3{font-family:var(--sans);font-size:1.05rem;font-weight:700;margin:0;color:var(--ink);text-transform:none;letter-spacing:-.01em;border-bottom:none;padding-bottom:0}
.topic ul{margin:14px 0 20px;padding:0;list-style:none}

/* ---- Pager & footer --------------------------------------------------- */
.pager{display:flex;justify-content:space-between;gap:16px;
  border-top:2px solid var(--ink);margin-top:34px;padding:16px 0 0;
  font-family:var(--sans);font-size:.8rem;font-weight:700}
.pager a{text-decoration:none}
.site-foot{border-top:1px solid var(--line);margin-top:48px;padding:24px 0 40px;
  font-family:var(--sans);font-size:.78rem;color:var(--ink-soft)}
.site-foot .widget{margin-bottom:12px}

@media (max-width:640px){
  body{font-size:16px}
  .hero h2{font-size:1.55rem}
  .post-head h1{font-size:1.6rem}
  .site-head{position:static}
}

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//
